 WHERE (user_id BETWEEN 'a4000000-0000-0000-0000-000000000001' AND 'a4000000-0000-0000-0000-000000000002' OR user_id BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004'));
DELETE FROM attempts WHERE (user_id BETWEEN 'a4000000-0000-0000-0000-000000000001' AND 'a4000000-0000-0000-0000-000000000002' OR user_id BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004');
DELETE FROM auth_sessions WHERE user_id BETWEEN 'a4000000-0000-0000-0000-000000000001' AND 'a4000000-0000-0000-0000-000000000002';
DELETE FROM user_roles WHERE user_id BETWEEN 'a4000000-0000-0000-0000-000000000001' AND 'a4000000-0000-0000-0000-000000000002';
DELETE FROM users WHERE user_id BETWEEN 'a4000000-0000-0000-0000-000000000001' AND 'a4000000-0000-0000-0000-000000000002';
